@Test
public void testPartitionAwareSegmentPruner() {
    Pql2Compiler compiler = new Pql2Compiler();
    BrokerRequest brokerRequest1 = compiler.compileToBrokerRequest(QUERY_1);
    BrokerRequest brokerRequest2 = compiler.compileToBrokerRequest(QUERY_2);
    BrokerRequest brokerRequest3 = compiler.compileToBrokerRequest(QUERY_3);
    // NOTE: External view and ideal state are not used in the current implementation.
    ExternalView externalView = Mockito.mock(ExternalView.class);
    IdealState idealState = Mockito.mock(IdealState.class);
    PartitionSegmentPruner segmentPruner = new PartitionSegmentPruner(OFFLINE_TABLE_NAME, PARTITION_COLUMN, _propertyStore);
    Set<String> onlineSegments = new HashSet<>();
    segmentPruner.init(externalView, idealState, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.emptyList()), Collections.emptyList());
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.emptyList()), Collections.emptyList());
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.emptyList()), Collections.emptyList());
    // Segments without metadata (not updated yet) should not be pruned
    String newSegment = "newSegment";
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.singletonList(newSegment)), Collections.singletonList(newSegment));
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.singletonList(newSegment)), Collections.singletonList(newSegment));
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.singletonList(newSegment)), Collections.singletonList(newSegment));
    // Segments without partition metadata should not be pruned
    String segmentWithoutPartitionMetadata = "segmentWithoutPartitionMetadata";
    onlineSegments.add(segmentWithoutPartitionMetadata);
    OfflineSegmentZKMetadata segmentZKMetadataWithoutPartitionMetadata = new OfflineSegmentZKMetadata();
    segmentZKMetadataWithoutPartitionMetadata.setSegmentName(segmentWithoutPartitionMetadata);
    ZKMetadataProvider.setOfflineSegmentZKMetadata(_propertyStore, OFFLINE_TABLE_NAME, segmentZKMetadataWithoutPartitionMetadata);
    segmentPruner.onExternalViewChange(externalView, idealState, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.singletonList(segmentWithoutPartitionMetadata)), Collections.singletonList(segmentWithoutPartitionMetadata));
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.singletonList(segmentWithoutPartitionMetadata)), Collections.singletonList(segmentWithoutPartitionMetadata));
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.singletonList(segmentWithoutPartitionMetadata)), Collections.singletonList(segmentWithoutPartitionMetadata));
    // Test different partition functions and number of partitions
    // 0 % 5 = 0; 1 % 5 = 1; 2 % 5 = 2
    String segment0 = "segment0";
    onlineSegments.add(segment0);
    setSegmentZKMetadata(segment0, "Modulo", 5, 0);
    // Murmur(0) % 4 = 0; Murmur(1) % 4 = 3; Murmur(2) % 4 = 0
    String segment1 = "segment1";
    onlineSegments.add(segment1);
    setSegmentZKMetadata(segment1, "Murmur", 4, 0);
    segmentPruner.onExternalViewChange(externalView, idealState, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
    assertEquals(segmentPruner.prune(brokerRequest2, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
    assertEquals(segmentPruner.prune(brokerRequest3, Arrays.asList(segment0, segment1)), Collections.singletonList(segment1));
    // Update partition metadata without refreshing should have no effect
    setSegmentZKMetadata(segment0, "Modulo", 4, 1);
    segmentPruner.onExternalViewChange(externalView, idealState, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
    assertEquals(segmentPruner.prune(brokerRequest2, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
    assertEquals(segmentPruner.prune(brokerRequest3, Arrays.asList(segment0, segment1)), Collections.singletonList(segment1));
    // Refresh the changed segment should update the segment pruner
    segmentPruner.refreshSegment(segment0);
    assertEquals(segmentPruner.prune(brokerRequest1, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
    assertEquals(segmentPruner.prune(brokerRequest2, Arrays.asList(segment0, segment1)), Collections.singletonList(segment1));
    assertEquals(segmentPruner.prune(brokerRequest3, Arrays.asList(segment0, segment1)), Arrays.asList(segment0, segment1));
}

