    serverMap.put(serverName(counter), s);
    ++counter;
    // server5 ... timing out server
    s = new FakeSizeServer(Arrays.asList("s1", "s3"));
    s.start(URI_PATH, createHandler(200, s.sizes, timeoutMsec * 100));
    serverMap.put(serverName(counter), s);
    ++counter;
}

